"use client";
import { useCallback, useEffect, useRef, useState } from "react";
import { fmt } from "@/lib/program";
import RaceStage from "@/components/RaceStage";

const GAME_NAMES = ["Dino Champions", "Rocket Race", "FPS Team Deathmatch", "Flappy Bird"] as const;

type GameProgress = {
  version: 1;
  total: number;
  racePoints?: number;
  submitted: boolean;
  confirmation?: string;
};

function parseGameProgress(value: string | null): GameProgress | null {
  if (!value) return null;
  try {
    const progress: unknown = JSON.parse(value);
    if (typeof progress !== "object" || progress === null) return null;
    const candidate = progress as Partial<GameProgress>;
    if (candidate.version !== 1 || !Number.isSafeInteger(candidate.total) || (candidate.total ?? -1) < 0
      || (candidate.racePoints !== undefined && (!Number.isSafeInteger(candidate.racePoints) || candidate.racePoints < 0))
      || typeof candidate.submitted !== "boolean") return null;
    return candidate as GameProgress;
  } catch {
    return null;
  }
}

async function clearWebsiteStorage(progressKey: string): Promise<string | null> {
  const progress = window.localStorage.getItem(progressKey);
  window.localStorage.clear();
  window.sessionStorage.clear();
  if (progress !== null) window.localStorage.setItem(progressKey, progress);

  const cookieNames = document.cookie
    .split(";")
    .map(cookie => cookie.trim().split("=")[0])
    .filter(Boolean);
  const pathSegments = window.location.pathname.split("/").filter(Boolean);
  const paths = ["/", ...pathSegments.map((_, index) => `/${pathSegments.slice(0, index + 1).join("/")}`)];
  for (const name of cookieNames) {
    for (const path of paths) {
      document.cookie = `${name}=; Max-Age=0; path=${path}; SameSite=Lax`;
    }
  }

  if (typeof indexedDB.databases === "function") {
    const databases = await indexedDB.databases();
    await Promise.all((databases ?? []).flatMap(database => database.name ? [
      new Promise<void>((resolve, reject) => {
        const request = indexedDB.deleteDatabase(database.name!);
        request.onsuccess = () => resolve();
        request.onerror = () => reject(request.error ?? new Error(`Could not delete IndexedDB database ${database.name}.`));
        request.onblocked = () => reject(new Error(`Deletion of IndexedDB database ${database.name} is blocked by another page.`));
      }),
    ] : []));
  }

  if ("caches" in window) {
    const cacheNames = await window.caches.keys();
    const deleted = await Promise.all(cacheNames.map(name => window.caches.delete(name)));
    if (deleted.some(success => !success)) throw new Error("Could not delete one or more website caches.");
  }

  if ("serviceWorker" in navigator) {
    const registrations = await navigator.serviceWorker.getRegistrations();
    const removed = await Promise.all(registrations.map(registration => registration.unregister()));
    if (removed.some(success => !success)) throw new Error("Could not unregister one or more website service workers.");
  }
  return progress;
}

export default function DinoGame({
  total,
  startsAt,
  endsAt,
  submissionDeadline,
  storageKey,
  competitionId,
  playerId,
  playerName,
  onSubmitFinal,
}: {
  total: number;
  startsAt: number;
  endsAt: number;
  submissionDeadline: number;
  storageKey: string;
  competitionId: string;
  playerId: string;
  playerName: string;
  onSubmitFinal: (total: number) => Promise<string>;
}) {
  const cv = useRef<HTMLCanvasElement>(null);
  const api = useRef<{ start(): void; jump(): void; duck(v: boolean): void; stop(): void }>({
    start() {},
    jump() {},
    duck() {},
    stop() {},
  });
  const [phase, setPhase] = useState<"ready" | "run" | "over" | "settling" | "ended" | "banned">("ready");
  const [storageReady, setStorageReady] = useState(false);
  const [clockNow, setClockNow] = useState(() => Math.floor(Date.now() / 1000));
  const [score, setScore] = useState(0);
  const [totalScore, setTotalScore] = useState(total);
  const [racePoints, setRacePoints] = useState(0);
  const gameDuration = Math.max(1, (endsAt - startsAt) / GAME_NAMES.length);
  const activeGameIndex = Math.min(
    GAME_NAMES.length - 1,
    Math.max(0, Math.floor((clockNow - startsAt) / gameDuration)),
  );
  const [msg, setMsg] = useState("");
  const [submissionState, setSubmissionState] = useState<"waiting" | "submitting" | "submitted" | "failed" | "closed">("waiting");
  const progressKey = `${storageKey}:progress`;
  const [banned, setBanned] = useState(() => {
    try {
      return typeof window !== "undefined" && window.localStorage.getItem(`${storageKey}:local-ban`) === "1";
    } catch {
      return false;
    }
  });
  const totalRef = useRef(total);
  const scoreList = useRef<number[]>(total > 0 ? [total] : []);
  const submissionStarted = useRef(false);
  const submissionComplete = useRef(false);
  const bannedRef = useRef(banned);
  const onChainTotalRef = useRef(total);
  const racePointsRef = useRef(0);
  const onSubmitFinalRef = useRef(onSubmitFinal);
  onSubmitFinalRef.current = onSubmitFinal;
  bannedRef.current = banned;
  onChainTotalRef.current = total;

  const banThisBrowser = useCallback(() => {
    if (bannedRef.current) return;
    bannedRef.current = true;
    scoreList.current = [];
    totalRef.current = 0;
    setTotalScore(0);
    setBanned(true);
    setPhase("banned");
    api.current.stop();
    try {
      window.localStorage.setItem(`${storageKey}:local-ban`, "1");
      setMsg("Developer tools may be open. To protect fair play, this competition has been locked in this browser.");
    } catch (error: unknown) {
      const reason = error instanceof Error ? error.message : String(error);
      setMsg(`Developer tools may be open. This page is locked for this session, but the browser could not save the local lock: ${reason}`);
    }
  }, [storageKey]);

  const submitFinalTotal = useCallback(async () => {
    if (bannedRef.current) {
      setMsg("This browser is locked out of this competition and cannot submit its score.");
      return;
    }
    if (submissionStarted.current || submissionComplete.current) return;
    const now = Math.floor(Date.now() / 1000);
    if (now < endsAt) {
      setMsg("The competition is still running. Your final total will be submitted when it ends.");
      return;
    }
    if (now > submissionDeadline) {
      setSubmissionState("closed");
      setPhase("ended");
      setMsg("The 60-second final-score submission window has closed.");
      return;
    }

    submissionStarted.current = true;
    setPhase("settling");
    setSubmissionState("submitting");
    setMsg(`Competition ended. Approve Phantom to submit your total score of ${totalRef.current} to Solana.`);
    try {
      const confirmation = await onSubmitFinalRef.current(totalRef.current);
      submissionComplete.current = true;
      setSubmissionState("submitted");
      setPhase("ended");
      setMsg(confirmation);
      try {
        window.localStorage.setItem(progressKey, JSON.stringify({
          version: 1,
          total: totalRef.current,
          racePoints: racePointsRef.current,
          submitted: true,
          confirmation,
        } satisfies GameProgress));
      } catch (error: unknown) {
        const reason = error instanceof Error ? error.message : String(error);
        setMsg(`${confirmation} The browser could not save the submission record: ${reason}`);
      }
    } catch (error: unknown) {
      const reason = error instanceof Error ? error.message : String(error);
      const windowOpen = Math.floor(Date.now() / 1000) <= submissionDeadline;
      setSubmissionState(windowOpen ? "failed" : "closed");
      setPhase("ended");
      setMsg(windowOpen
        ? `Final score not submitted: ${reason}. Retry before the 60-second submission window closes.`
        : `Final score was not submitted: ${reason}. The 60-second submission window has closed.`);
    } finally {
      submissionStarted.current = false;
    }
  }, [endsAt, progressKey, submissionDeadline]);

  const recordRaceScore = useCallback((delta: number, totalPoints: number) => {
    if (delta <= 0) return;
    racePointsRef.current = totalPoints;
    setRacePoints(totalPoints);
    scoreList.current = [...scoreList.current, delta];
    totalRef.current = scoreList.current.reduce((sum, value) => sum + value, 0);
    setTotalScore(totalRef.current);
    try {
      window.localStorage.setItem(progressKey, JSON.stringify({
        version: 1,
        total: totalRef.current,
        racePoints: totalPoints,
        submitted: false,
      } satisfies GameProgress));
    } catch (error: unknown) {
      const reason = error instanceof Error ? error.message : String(error);
      setMsg(`Race points are in memory but could not be saved for a reload: ${reason}`);
    }
  }, [progressKey]);

  useEffect(() => {
    const timer = window.setInterval(() => setClockNow(Math.floor(Date.now() / 1000)), 1000);
    return () => window.clearInterval(timer);
  }, []);

  useEffect(() => {
    if (activeGameIndex > 0 && clockNow < endsAt) {
      setScore(0);
      setMsg("");
      setPhase("ready");
    }
  }, [activeGameIndex, endsAt]);

  useEffect(() => {
    let active = true;
    void clearWebsiteStorage(progressKey).then(progressValue => {
      if (!active) return;
      const progress = parseGameProgress(progressValue);
      const onChainTotal = onChainTotalRef.current;
      const restoredTotal = progress?.total ?? onChainTotal;
      const alreadySubmitted = !!progress?.submitted
        || (Date.now() / 1000 >= endsAt && onChainTotal > 0 && (!progress || progress.total === onChainTotal));
      scoreList.current = restoredTotal > 0 ? [restoredTotal] : [];
      totalRef.current = restoredTotal;
      racePointsRef.current = progress?.racePoints ?? 0;
      setRacePoints(racePointsRef.current);
      setTotalScore(restoredTotal);
      if (alreadySubmitted) {
        submissionComplete.current = true;
        setSubmissionState("submitted");
        setPhase("ended");
        setMsg(progress?.confirmation ?? `Final total ${onChainTotal} is already recorded on-chain.`);
      } else {
        try {
          window.localStorage.setItem(progressKey, JSON.stringify({
            version: 1,
            total: restoredTotal,
            racePoints: racePointsRef.current,
            submitted: false,
          } satisfies GameProgress));
        } catch (error: unknown) {
          const reason = error instanceof Error ? error.message : String(error);
          setPhase("ended");
          setMsg(`Could not save game progress in this browser: ${reason}`);
          return;
        }
      }
      if (bannedRef.current) window.localStorage.setItem(`${storageKey}:local-ban`, "1");
      setStorageReady(true);
    }).catch((error: unknown) => {
      if (!active) return;
      const reason = error instanceof Error ? error.message : String(error);
      setPhase("ended");
      setMsg(`Could not clear this website's browser storage before play: ${reason}`);
    });
    return () => { active = false; };
  }, [endsAt, progressKey, storageKey]);

  useEffect(() => {
    if (!storageReady || bannedRef.current) return;
    const checkDevTools = () => {
      const dockedWidth = window.outerWidth - window.innerWidth;
      const dockedHeight = window.outerHeight - window.innerHeight;
      if (dockedWidth > 200 || dockedHeight > 200) banThisBrowser();
    };
    checkDevTools();
    const interval = window.setInterval(checkDevTools, 500);
    window.addEventListener("resize", checkDevTools);
    window.addEventListener("focus", checkDevTools);
    return () => {
      window.clearInterval(interval);
      window.removeEventListener("resize", checkDevTools);
      window.removeEventListener("focus", checkDevTools);
    };
  }, [banThisBrowser, storageReady]);

  useEffect(() => {
    if (!storageReady || bannedRef.current) return;
    const canvas = cv.current;
    const context = canvas?.getContext("2d");
    if (!context) {
      setPhase("ended");
      setMsg("Your browser could not initialize the game canvas.");
      return;
    }

    const x = context, W = 640, G = 160, birdX = 120, cs = getComputedStyle(document.documentElement);
    const ink = cs.getPropertyValue("--ink"), mut = cs.getPropertyValue("--mut"), bg = cs.getPropertyValue("--card"), acc = cs.getPropertyValue("--acc"), warn = cs.getPropertyValue("--warn");
    let yf = G, vy = 0, birdY = 100, birdVelocity = 0, duck = false, activeGame: "dino" | "flappy" | "shooter" = "dino", activeSlot = 0;
    let obs: { x: number; y: number; w: number; h: number; b?: number }[] = [];
    let pipes: { x: number; gapY: number; scored: boolean }[] = [];
    let sp = 6, sc = 0, gap = 80, f = 0, run = false, last = 0, raf = 0, expired = false;
    const gnd = () => yf >= G, hh = () => (duck && gnd() ? 22 : 40);
    const isCompetitionStarted = () => Date.now() / 1000 >= startsAt;
    const isCompetitionOver = () => Date.now() / 1000 >= endsAt;
    const gameIndexAt = (now: number) => Math.min(GAME_NAMES.length - 1, Math.max(0, Math.floor((now - startsAt) / gameDuration)));
    const addRunScore = (value: number) => {
      scoreList.current = [...scoreList.current, Math.max(0, Math.floor(value))];
      totalRef.current = scoreList.current.reduce((sum, entry) => sum + entry, 0);
      setTotalScore(totalRef.current);
      try {
        window.localStorage.setItem(progressKey, JSON.stringify({
          version: 1,
          total: totalRef.current,
          racePoints: racePointsRef.current,
          submitted: false,
        } satisfies GameProgress));
      } catch (error: unknown) {
        const reason = error instanceof Error ? error.message : String(error);
        setMsg(`Your score is in memory but could not be saved for a reload: ${reason}`);
      }
    };

    const draw = () => {
      x.fillStyle = bg; x.fillRect(0, 0, W, 200);
      if (activeGame === "flappy") {
        pipes.forEach(pipe => {
          const gapTop = pipe.gapY - 36, gapBottom = pipe.gapY + 36;
          x.fillStyle = acc;
          x.fillRect(pipe.x, 0, 48, gapTop);
          x.fillRect(pipe.x, gapBottom, 48, 200 - gapBottom);
          x.fillStyle = mut;
          x.fillRect(pipe.x - 4, gapTop - 8, 56, 8);
          x.fillRect(pipe.x - 4, gapBottom, 56, 8);
        });
        x.fillStyle = warn;
        x.beginPath(); x.arc(birdX, birdY, 12, 0, Math.PI * 2); x.fill();
        x.fillStyle = ink;
        x.beginPath(); x.arc(birdX + 4, birdY - 3, 2, 0, Math.PI * 2); x.fill();
        x.fillStyle = acc;
        x.beginPath(); x.moveTo(birdX + 10, birdY); x.lineTo(birdX + 19, birdY + 3); x.lineTo(birdX + 10, birdY + 6); x.fill();
        return;
      }
      x.fillStyle = mut; x.fillRect(0, G + 1, W, 2);
      const h = hh(), top = yf - h; x.fillStyle = ink;
      if (h === 22) { x.fillRect(40, top, 44, h); x.fillStyle = bg; x.fillRect(76, top + 4, 4, 4); }
      else {
        x.fillRect(40, top + 10, 30, h - 18); x.fillRect(52, top, 26, 18);
        x.fillStyle = bg; x.fillRect(68, top + 4, 4, 4); x.fillStyle = ink;
        const leg = gnd() && Math.floor(f / 5) % 2;
        x.fillRect(44, top + h - 8, 8, leg ? 8 : 4); x.fillRect(58, top + h - 8, 8, leg ? 4 : 8);
      }
      obs.forEach(o => {
        x.fillStyle = o.b ? mut : acc;
        if (o.b) {
          x.fillRect(o.x, o.y, o.w, o.h);
          x.fillRect(o.x + 6, o.y + (Math.floor(f / 8) % 2 ? -8 : o.h), 14, 8);
        } else {
          x.fillRect(o.x + o.w / 2 - 4, o.y, 8, o.h);
          x.fillRect(o.x, o.y + 8, o.w / 2, 6); x.fillRect(o.x + o.w / 2, o.y + 14, o.w / 2, 6);
        }
      });
    };

    const stop = () => {
      if (expired) return;
      expired = true;
      if (submissionComplete.current) {
        run = false;
        cancelAnimationFrame(raf);
        setPhase("ended");
        setSubmissionState("submitted");
        return;
      }
      if (run) addRunScore(sc);
      run = false;
      cancelAnimationFrame(raf);
      draw();
      if (bannedRef.current) {
        setPhase("banned");
        return;
      }
      setPhase("settling");
      if (Date.now() / 1000 <= submissionDeadline) {
        void submitFinalTotal();
      } else {
        setSubmissionState("closed");
        setPhase("ended");
        setMsg("Competition ended and the final-score submission window has closed.");
      }
    };
    const jump = () => {
      if (!run) return;
      if (activeGame === "flappy") birdVelocity = -6.5;
      else if (gnd()) vy = -12.5;
    };
    const dk = (value: boolean) => { if (run) duck = value; };
    const kd = (e: KeyboardEvent) => {
      if (e.code === "Space" || e.code === "ArrowUp") { e.preventDefault(); jump(); }
      if (e.code === "ArrowDown") { e.preventDefault(); dk(true); }
    };
    const ku = (e: KeyboardEvent) => { if (e.code === "ArrowDown") dk(false); };
    window.addEventListener("keydown", kd);
    window.addEventListener("keyup", ku);
    const onShooterScore = (event: MessageEvent) => {
      if (event.origin !== window.location.origin || activeGame !== "shooter" || !run || !isCompetitionStarted() || isCompetitionOver()) return;
      const data = event.data as { type?: unknown; points?: unknown } | null;
      if (!data || data.type !== "tdm-score" || !Number.isSafeInteger(data.points) || (data.points as number) < 1 || (data.points as number) > 1) return;
      sc += 1;
      setScore(Math.floor(sc));
    };
    window.addEventListener("message", onShooterScore);

    function loop(n: number) {
      if (!run) return;
      if (isCompetitionOver()) { stop(); return; }
      const currentSlot = gameIndexAt(Date.now() / 1000);
      if (currentSlot !== activeSlot) {
        addRunScore(sc);
        run = false;
        activeSlot = currentSlot;
        activeGame = currentSlot === 2 ? "shooter" : currentSlot === 3 ? "flappy" : "dino";
        sc = 0;
        setScore(0);
        setPhase("ready");
        draw();
        return;
      }
      const k = Math.min((n - last) / 16.7, 3);
      last = n; f += k;
      if (activeGame === "shooter") {
        raf = requestAnimationFrame(loop);
        return;
      }
      if (activeGame === "flappy") {
        birdVelocity += 0.38 * k;
        birdY += birdVelocity * k;
        gap -= 3.2 * k;
        if (gap <= 0) {
          pipes.push({ x: W, gapY: 52 + Math.random() * 96, scored: false });
          gap = 185;
        }
        pipes.forEach(pipe => { pipe.x -= 3.2 * k; });
        pipes = pipes.filter(pipe => pipe.x > -60);
        for (const pipe of pipes) {
          if (!pipe.scored && pipe.x + 48 < birdX) {
            pipe.scored = true;
            sc += 1;
          }
        }
        const hitPipe = pipes.some(pipe => {
          const gapTop = pipe.gapY - 36, gapBottom = pipe.gapY + 36;
          const overlapsX = birdX + 10 > pipe.x && birdX - 10 < pipe.x + 48;
          return overlapsX && (birdY - 10 < gapTop || birdY + 10 > gapBottom);
        });
        if (hitPipe || birdY - 12 < 0 || birdY + 12 > 200) {
          run = false; draw();
          addRunScore(sc);
          setScore(Math.floor(sc));
          setPhase("over");
          return;
        }
      } else {
        sp += 0.0025 * k; sc += sp * k * 0.06;
        vy += 0.7 * k; yf = Math.min(G, yf + vy * k); if (gnd()) vy = 0;
        gap -= sp * k;
        if (gap <= 0) {
          const bird = sc > 120 && Math.random() < 0.3, h = 30 + Math.floor(Math.random() * 18);
          obs.push(bird ? { x: W, y: G - 52, w: 30, h: 18, b: 1 } : { x: W, w: 14 + Math.floor(Math.random() * 14), h, y: G - h });
          gap = 260 + Math.random() * 260 + sp * 18;
        }
        obs.forEach(o => { o.x -= sp * k; });
        obs = obs.filter(o => o.x > -40);
        const top = yf - hh();
        if (obs.some(o => 72 > o.x && 44 < o.x + o.w && yf - 4 > o.y && top + 4 < o.y + o.h)) {
          run = false; draw();
          addRunScore(sc);
          setScore(Math.floor(sc));
          setPhase("over");
          return;
        }
      }
      setScore(Math.floor(sc)); draw(); raf = requestAnimationFrame(loop);
    }

    api.current = {
      jump,
      duck: dk,
      start() {
        if (!isCompetitionStarted()) {
          setMsg("The competition has not started yet.");
          return;
        }
        if (isCompetitionOver()) { stop(); return; }
        activeSlot = gameIndexAt(Date.now() / 1000);
        if (activeSlot === 1) {
          setMsg("The multiplayer race starts automatically during the second stage.");
          return;
        }
        activeGame = activeSlot === 2 ? "shooter" : activeSlot === 3 ? "flappy" : "dino";
        yf = G; vy = 0; birdY = 100; birdVelocity = 0; duck = false; obs = []; pipes = []; sp = 6; sc = 0; gap = activeGame === "flappy" ? 0 : 80; f = 0;
        run = true; last = performance.now(); setScore(0); setMsg(""); setPhase("run");
        draw();
        raf = requestAnimationFrame(loop);
      },
      stop,
    };
    draw();
    if (isCompetitionOver()) stop();
    const endTimer = window.setTimeout(stop, Math.max(0, endsAt * 1000 - Date.now()));
    const submissionTimer = window.setTimeout(() => {
      if (Date.now() / 1000 > submissionDeadline) {
        setSubmissionState(current => current === "submitted" ? current : "closed");
        setPhase("ended");
        setMsg(current => current || "The final-score submission window has closed.");
      }
    }, Math.max(0, submissionDeadline * 1000 - Date.now() + 1000));
    return () => {
      run = false;
      cancelAnimationFrame(raf);
      clearTimeout(endTimer);
      clearTimeout(submissionTimer);
      window.removeEventListener("keydown", kd);
      window.removeEventListener("keyup", ku);
      window.removeEventListener("message", onShooterScore);
    };
  }, [endsAt, startsAt, storageReady, submissionDeadline, submitFinalTotal]);

  if (banned) return <section className="game-lockout" role="alert" aria-labelledby="game-lockout-title">
    <div className="game-lockout-icon" aria-hidden="true">
      <svg viewBox="0 0 24 24" fill="none">
        <path d="M7.5 10V7.5a4.5 4.5 0 0 1 9 0V10M6.5 10h11a1.5 1.5 0 0 1 1.5 1.5v8a1.5 1.5 0 0 1-1.5 1.5h-11A1.5 1.5 0 0 1 5 19.5v-8A1.5 1.5 0 0 1 6.5 10Z" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" />
        <path d="M12 14v3" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" />
      </svg>
    </div>
    <div className="game-lockout-copy">
      <span className="game-lockout-eyebrow">Fair-play protection</span>
      <h3 id="game-lockout-title">Competition locked</h3>
      <p>{msg || "Developer tools may be open. To protect fair play, this competition has been locked in this browser."}</p>
      <p className="game-lockout-detail">Play and score submission are disabled for this competition in this browser. This automatic check can be mistaken and is only a browser-side restriction.</p>
    </div>
  </section>;

  return <div>
    <div className="top" style={{ margin: "10px 2px", fontWeight: 700 }}>
      <span>Game {activeGameIndex + 1}/{GAME_NAMES.length}: {GAME_NAMES[activeGameIndex]} · run score <span className="mono">{score}</span></span>
      <span className="mut">Competition total <span className="mono">{totalScore}</span></span>
    </div>
    <div className="sm mut" style={{ margin: "0 2px 8px" }}>
      {GAME_NAMES.map((name, index) => {
        const slotStart = startsAt + gameDuration * index;
        const slotEnd = startsAt + gameDuration * (index + 1);
        return <span key={name} style={{ marginRight: 12, fontWeight: activeGameIndex === index ? 700 : 400 }}>
          {index + 1}. {name}: {fmt(gameDuration)} ({fmt(slotStart - startsAt)}–{fmt(slotEnd - startsAt)})
        </span>;
      })}
    </div>
    <div className="gw">
      <canvas ref={cv} width={640} height={200} onPointerDown={() => api.current.jump()} style={{ display: activeGameIndex === 1 || activeGameIndex === 2 ? "none" : "block" }} />
      {activeGameIndex === 2 && phase === "run" && <iframe title="FPS Team Deathmatch" src="/team-deathmatch.html?competition=1" style={{ display: "block", width: "100%", height: "min(72vh, 680px)", minHeight: 440, border: 0, background: "#111" }} allow="fullscreen; pointer-lock" />}
      {activeGameIndex === 1 && storageReady && <RaceStage
        competitionId={competitionId}
        playerId={playerId}
        playerName={playerName}
        initialPoints={racePoints}
        onScore={recordRaceScore}
      />}
      {phase !== "run" && activeGameIndex !== 1 && activeGameIndex !== 2 && <div className="ov">
        <b style={{ fontSize: 22 }}>{phase === "ready" ? clockNow < startsAt ? "Competition has not started" : `Ready for ${GAME_NAMES[activeGameIndex]}` : phase === "over" ? "Game over" : phase === "settling" ? "Processing competition scores" : phase === "banned" ? "Competition locked" : "Competition ended"}</b>
        {phase === "over" && <div className="mono" style={{ fontSize: 30 }}>{score}</div>}
        {phase === "settling" && <div className="mono">Final total: {totalScore}</div>}
        {(phase === "settling" || phase === "ended") && <div className="sm mut" role="status">{msg}</div>}
        {phase === "settling" && submissionState === "submitting" && <div className="sm">Waiting for Phantom approval and Solana confirmation…</div>}
        {(phase === "settling" || phase === "ended") && submissionState === "failed" && Date.now() / 1000 <= submissionDeadline &&
          <button className="btn sec" onClick={() => void submitFinalTotal()}>Submit final total again</button>}
        {(phase === "ready" || phase === "over") && <button className="btn" disabled={phase === "ready" && (!storageReady || clockNow < startsAt)} onClick={() => api.current.start()}>
          {phase === "ready" ? !storageReady ? "Clearing website storage…" : clockNow < startsAt ? `Starts in ${Math.max(0, startsAt - clockNow)}s` : "Start" : "Play again"}
        </button>}
      </div>}
    </div>
    <p className="sm mut">
      The competition is split evenly across four stages: Dino Champions, multiplayer Rocket Race, FPS Team Deathmatch, then Flappy Bird.
      Use Space / ↑ to jump or flap, ↓ to duck in Dino Champions, the race controls during Rocket Race, and WASD + mouse in FPS Team Deathmatch. FPS kills count toward your competition score.
      Scores from all four games are added to your competition total and saved in this browser.
      At the end, approve one Phantom transaction to submit your final total.
    </p>
  </div>;
}
